with metrics as (select *, avg(cost) over (partition by supplier_id, brand order by price, id rows between 6 preceding and current row) as cost_avg_6, lag(cost, 2, 0) over w_running as prev_cost from products where category = 'Sports' window w_running as (partition by brand order by launch_date, id)) select id, product_name, category, brand, cost, stock_qty, launch_date, tags, cost_avg_6 from metrics order by category desc nulls last, stock_qty
